            "id": "rc48-2-l2",
            "speaker": "B",
            "jp": "ええ、<ruby>毎日<rt>まいにち</rt></ruby> <u><ruby>自分<rt>じぶん</rt></ruby>の <ruby>部屋<rt>へや</rt></ruby>を <ruby>掃除<rt>そうじ</rt></ruby>させて</u> います。",
            "rawJp": "ええ、毎日 自分の 部屋を 掃除させて います。",
